import { useState, useEffect, useCallback, type ReactNode } from "react";
import {
  IconBoard,
  IconTrigger,
  IconContext,
  IconDraft,
  IconDelivery,
  IconSettings,
  IconSearch,
  IconMenu,
  IconSun,
  IconMoon,
  IconFilter,
} from "./Icons";

export type PageKey = "board" | "trigger" | "context" | "draft" | "delivery" | "settings";

interface NavItem {
  key: PageKey;
  label: string;
  icon: ReactNode;
}

const NAV_ITEMS: NavItem[] = [
  { key: "board", label: "看板", icon: <IconBoard /> },
  { key: "trigger", label: "触发", icon: <IconTrigger /> },
  { key: "context", label: "上下文", icon: <IconContext /> },
  { key: "draft", label: "草稿", icon: <IconDraft /> },
  { key: "delivery", label: "交付", icon: <IconDelivery /> },
];

interface Toast {
  id: number;
  title: string;
  message?: string;
  type: "success" | "error" | "info";
}

let toastId = 0;
let toastListeners: ((toast: Toast) => void)[] = [];

export function showToast(title: string, message?: string, type: "success" | "error" | "info" = "info") {
  const toast: Toast = { id: ++toastId, title, message, type };
  toastListeners.forEach((fn) => fn(toast));
}

function ToastContainer() {
  const [toasts, setToasts] = useState<Toast[]>([]);

  useEffect(() => {
    const listener = (toast: Toast) => {
      setToasts((prev) => [...prev, toast]);
      setTimeout(() => {
        setToasts((prev) => prev.filter((t) => t.id !== toast.id));
      }, 3500);
    };
    toastListeners.push(listener);
    return () => {
      toastListeners = toastListeners.filter((fn) => fn !== listener);
    };
  }, []);

  return (
    <div className="fixed top-4 right-4 z-[100] flex flex-col gap-2 pointer-events-none">
      {toasts.map((t) => (
        <div
          key={t.id}
          className={`pointer-events-auto min-w-[260px] max-w-[360px] rounded-lg border px-4 py-3 shadow-xl backdrop-blur-xl toast-enter ${
            t.type === "success"
              ? "bg-emerald-500/15 border-emerald-500/25 text-emerald-300"
              : t.type === "error"
              ? "bg-red-500/15 border-red-500/25 text-red-300"
              : "bg-zinc-800/90 border-zinc-700/50 text-zinc-200"
          }`}
        >
          <div className="text-sm font-medium">{t.title}</div>
          {t.message && <div className="text-xs opacity-70 mt-0.5">{t.message}</div>}
        </div>
      ))}
    </div>
  );
}

interface LayoutProps {
  currentPage: PageKey;
  onNavigate: (page: PageKey) => void;
  chatOpen: boolean;
  onCloseChat?: () => void;
  children: ReactNode;
  chatPanel: ReactNode;
}

function useIsMobile(): boolean {
  const [isMobile, setIsMobile] = useState(window.innerWidth <= 768);
  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth <= 768);
    window.addEventListener("resize", handleResize);
    return () => window.removeEventListener("resize", handleResize);
  }, []);
  return isMobile;
}

export function Layout({ currentPage, onNavigate, chatOpen, onCloseChat, children, chatPanel }: LayoutProps) {
  const isMobile = useIsMobile();
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [darkMode, setDarkMode] = useState(() => {
    const saved = localStorage.getItem("asa-theme");
    return saved ? saved === "dark" : true;
  });

  useEffect(() => {
    document.documentElement.classList.toggle("dark", darkMode);
    localStorage.setItem("asa-theme", darkMode ? "dark" : "light");
  }, [darkMode]);

  useEffect(() => {
    setSidebarOpen(false);
  }, [currentPage]);

  const handleNavClick = (page: PageKey) => {
    onNavigate(page);
    if (isMobile) setSidebarOpen(false);
  };

  const showMobileNav = isMobile && currentPage !== "board";

  return (
    <div className={`app-container ${chatOpen ? "chat-open" : ""}`}>
      <ToastContainer />
      <div className="top-bar">
        <div className="top-bar-left">
          <button
            className="icon-btn hamburger-btn"
            onClick={() => setSidebarOpen(!sidebarOpen)}
            aria-label="菜单"
          >
            <IconMenu />
          </button>

          <div className="top-bar-logo">
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#10b981" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round">
              <path d="M13 10V3L4 14h7v7l9-11h-7z" />
            </svg>
            <span className="hidden sm:inline">Async Starter Agent</span>
          </div>
        </div>

        <div className="top-bar-search">
          <div className="top-bar-search-inner">
            <div className="top-bar-search-icon">
              <IconSearch />
            </div>
            <input
              type="text"
              placeholder="输入指令快速触发 Agent..."
            />
          </div>
        </div>

        <div className="top-bar-actions">
          <button className="icon-btn" onClick={() => setDarkMode(!darkMode)} aria-label="切换主题">
            {darkMode ? <IconSun /> : <IconMoon />}
          </button>
          <button className="icon-btn" aria-label="筛选">
            <IconFilter />
          </button>
        </div>
      </div>

      {sidebarOpen && isMobile && (
        <div className="sidebar-overlay show" onClick={() => setSidebarOpen(false)} />
      )}

      <div className="main-content">
        <nav className={`sidebar ${sidebarOpen ? "show" : ""}`}>
          {NAV_ITEMS.map((item) => (
            <button
              key={item.key}
              className={`sidebar-item ${currentPage === item.key ? "active" : ""}`}
              onClick={() => handleNavClick(item.key)}
            >
              {item.icon}
              <span>{item.label}</span>
            </button>
          ))}
          <div className="sidebar-divider" />
          <button
            className={`sidebar-item ${currentPage === "settings" ? "active" : ""}`}
            onClick={() => handleNavClick("settings")}
          >
            <IconSettings />
            <span>设置</span>
          </button>
        </nav>

        {currentPage === "board" ? (
          <>
            <div className="kanban-area">{children}</div>
            {chatPanel}
          </>
        ) : (
          <div className="page-content">{children}</div>
        )}
      </div>

      {showMobileNav && (
        <div className="mobile-bottom-nav">
          {NAV_ITEMS.map((item) => (
            <button
              key={item.key}
              className={`mobile-bottom-nav-item ${currentPage === item.key ? "active" : ""}`}
              onClick={() => handleNavClick(item.key)}
            >
              {item.icon}
              <span>{item.label}</span>
            </button>
          ))}
        </div>
      )}
    </div>
  );
}

export type { LayoutProps };
